import{z as p,x as B,o as r,c as d,q as l,j as i,D as n,d as e,s,S as E,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Kolmogorov 复杂度","description":"","frontmatter":{"title":"Kolmogorov 复杂度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kolmogorov-complexity.md","filePath":"cs/kolmogorov-complexity.md","lastUpdated":1791063341000}'),A={name:"cs/kolmogorov-complexity.md"};function m(x,o,K,h,c,f){const t=B("Mermaid");return r(),d("div",null,[o[2]||(o[2]=l('<h1 id="kolmogorov-复杂度" tabindex="-1">Kolmogorov 复杂度 <a class="header-anchor" href="#kolmogorov-复杂度" aria-label="Permalink to &quot;Kolmogorov 复杂度&quot;">​</a></h1><div class="epigraph"><p>串 $x$ 的复杂度是打印 $x$ 然后停机的最短程序长度；几乎所有串都接近最大，而 $K$ 本身不可计算。</p><footer>—— 据 Kolmogorov, 1965；Chaitin；Li and Vitányi, An Introduction to Kolmogorov Complexity 整理</footer></div><p>上一课<a href="/cs/recursion-theorem">递归定理</a>让程序可以谈自身。缺口是给串一个<strong>描述长度</strong>，不依赖概率。<a href="/cs/entropy-bits">熵</a>是分布上的平均；这里单根串、最坏描述。本课钉 \\(K(x)\\)、不可计算、与随机串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定通用 TM（前缀自由或普通，差一个加性常数）。\\(K(x)=\\min\\{|p|:\\ U(p)=x\\}\\)。显然 \\(K(x)\\le |x|+O(1)\\)（硬编码）。不可计算：若 \\(K\\) 可计算，可枚举「\\(K(x)\\ge n\\) 的最短 \\(x\\)」，其描述「第 \\(n\\) 个不可压缩串」长度 \\(O(\\log n)\\)，矛盾——Berry 悖论的可计算版，合法性靠递归定理。</p><p>随机串： \\(K(x)\\ge |x|-c\\)。多数串如此（计数：短程序太少）。这与「通过统计检验」不同，但是 Martin-Löf 随机在前缀 \\(K\\) 下可对齐，本课点名。</p><h3 id="不是-shannon-熵" tabindex="-1">不是 Shannon 熵 <a class="header-anchor" href="#不是-shannon-熵" aria-label="Permalink to &quot;不是 Shannon 熵&quot;">​</a></h3><p>熵要 \\(p(x)\\)。均匀分布下典型串的 \\(K\\) 约 \\(n\\)，与熵同阶；换分布，熵低的源仍有个别高 \\(K\\) 的串。不要把压缩软件的输出长度写成 \\(K\\)——那是上界，且相对具体格式。</p><p><span class="marginnote">Kolmogorov 1965；Solomonoff、Chaitin 同期。Li–Vitányi 是标准书。前缀复杂度 \\(K\\) 让 Kraft 不等式可用；课堂常先讲普通 \\(C(x)\\)，差 \\(O(\\log n)\\)。</span></p><p><span class="marginnote">直觉类比：\\(K(x)\\) 就是「这份串的最短自解压说明书有多长」。常数串 \\(0101\\cdots01\\) 的说明书只要一句「把 01 重复 \\(n/2\\) 次」；而一枚抛硬币结果的串几乎只能照抄，说明书和原文一样长——后者就是随机串。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明不可计算用「最短不可压缩」自指。应用：不可压缩串没有短循环、不能有太长的 \\(0\\) 段（否则可描述）。条件 \\(K(x\\mid y)\\) 点名，不展开链规则全文。</p>',12)),(r(),i(E,null,{default:n(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%B8%B2%20x%22%5D%20--%3E%20P%5B%22%E6%9C%80%E7%9F%AD%E7%A8%8B%E5%BA%8F%20p%22%5D%0A%20%20P%20--%3E%20K%5B%22K(x)%3D%7Cp%7C%22%5D%0A%20%20K%20--%3E%20UNC%5B%22K%20%E4%B8%8D%E5%8F%AF%E8%AE%A1%E7%AE%97%22%5D%0A%20%20K%20--%3E%20RAND%5B%22K%E2%89%88%7Cx%7C%EF%BC%9A%E9%9A%8F%E6%9C%BA%E4%B8%B2%22%5D%0A"})]),fallback:n(()=>[...o[0]||(o[0]=[e(" Loading... ",-1)])]),_:1})),o[3]||(o[3]=a("p",null,[a("a",{href:"/cs/source-coding-theorem"},"信源编码"),e("那里平均码长对 Shannon。这里单串、最坏、相对通用机。")],-1)),o[4]||(o[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),o[5]||(o[5]=a("p",null,"\\(K\\) 对可计算变换几乎不变（加常数或对数）。故「是否随机」不依赖编程语言，只要通用。不可判定性：集合 \\(\\{x:K(x)\\ge |x|/2\\}\\) 不可判定。这比停机更「量」：每个串都有一个数，只是算不出。",-1)),(r(),i(E,null,{default:n(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%95%BF%E4%B8%BA%20n%20%E7%9A%84%E4%B8%B2%E6%9C%89%E5%A4%9A%E5%B0%91%3F%202%5En%20%E4%B8%AA%22%5D%20--%3E%20A%5B%22%E9%95%BF%E4%B8%8D%E8%B6%B3%20n%20%E7%9A%84%E7%A8%8B%E5%BA%8F%E6%9C%80%E5%A4%9A%202%5En%20-%201%20%E4%B8%AA%22%5D%0A%20%20A%20--%3E%20B%5B%22%E4%B8%80%E4%B8%AA%E7%A8%8B%E5%BA%8F%E5%8F%AA%E6%89%93%E5%8D%B0%E4%B8%80%E4%B8%AA%E4%B8%B2%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%BF%85%E6%9C%89%20n%20%E4%BD%8D%E4%B8%B2%E6%89%BE%E4%B8%8D%E5%88%B0%E6%9B%B4%E7%9F%AD%E7%9A%84%E6%8F%8F%E8%BF%B0%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8E%A8%E5%88%B0%E6%9E%81%E9%99%90%3A%20%E5%A4%9A%E6%95%B0%E4%B8%B2%20K(x)%20%E2%89%88%20n%2C%20%E4%B8%8D%E5%8F%AF%E5%8E%8B%E7%BC%A9%22%5D%0A"})]),fallback:n(()=>[...o[1]||(o[1]=[e(" Loading... ",-1)])]),_:1})),o[6]||(o[6]=l('<p>不要用 \\(K\\) 当文件压缩的目标函数去优化——不可计算。</p><p><span class="marginnote">数字实例：\\(n=10\\) 时长为 10 的串有 \\(2^{10}=1024\\) 个，而长度不足 10 的程序总共只有 \\(2^{10}-1=1023\\) 个——抽屉原理保证至少一个串压不掉；程序每短一位，能盖住的串就少一半，所以「多数串随机」。</span></p><p><span class="marginnote">常见误区：「\\(K\\) 不可计算」不等于「\\(K\\) 不存在」。每个串都有一个确定的 \\(K\\) 值，像每块石头都有重量，只是没有任何程序能把这块「秤」造出来——想算某个串的 \\(K\\)，会先撞上停机问题。</span></p><p>条件复杂度 \\(K(x\\mid y)\\) 是已知 \\(y\\) 时打印 \\(x\\) 的最短程序。对称性 \\(K(x,y)\\approx K(x)+K(y\\mid x)\\) 差对数项。不可压缩串通过几乎所有可计算统计检验，这是 Martin-Löf 随机的桥，本课不把测度论写完。压缩器给出的长度永远是 \\(K\\) 的上界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Martin-Löf 的测度论定义，不引入算法信息的缺一性引理全文。不把大模型的「压缩即智能」写成定理。后课默认：\\(K(x)\\) 是最短程序长，不可计算；随机串是不可压缩串。下一课换模型：λ 演算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(K(x)\\) = 输出 \\(x\\) 的最短程序长；相对通用机差常数。</li><li>\\(K\\) 不可计算；多数串不可压缩。</li><li>与 Shannon 熵分工：单串 vs 分布。</li><li>出处：Kolmogorov, 1965；Li and Vitányi。</li></ul>',8))])}const D=p(A,[["render",m]]);export{u as __pageData,D as default};
